import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('sales_data.xlsx') as z:
    print("=== files in archive ===")
    for n in z.namelist():
        print(n)
    print()
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    for sh in wb.find('m:sheets', NS):
        print("sheet:", sh.attrib)
    print()
    for name in z.namelist():
        if name.startswith('xl/worksheets/sheet'):
            print(f"=== {name} ===")
            root = ET.fromstring(z.read(name))
            sd = root.find('m:sheetData', NS)
            for row in sd.findall('m:row', NS)[:10]:
                cells = []
                for c in row.findall('m:c', NS):
                    cells.append((c.attrib.get('r'), c.attrib.get('t'), c.text))
                print(cells)

import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def cell_text(c):
    t = c.attrib.get('t')
    if t == 'inlineStr':
        is_el = c.find('m:is', NS)
        return ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
    return c.text

with zipfile.ZipFile('sales_data.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    sd = root.find('m:sheetData', NS)
    rows = sd.findall('m:row', NS)
    print("total rows:", len(rows))
    for row in rows:
        cells = {}
        for c in row.findall('m:c', NS):
            cells[c.attrib.get('r')] = cell_text(c)
        print(row.attrib.get('r'), cells)

